---Init 初始化
function GachaCoinQuestComponent:Init(jsonData)
    if nil == self.gachaCoinQuestDojo then
        self.gachaCoinQuestDojo = GachaCoinQuestDojo.New()
    end
    self.gachaCoinQuestDojo:Fill(jsonData)
end

