---GiveUpQuest 放弃任务
function GachaCoinQuestComponent:GiveUpQuest()
    -- 清空当前任务id
    self.gachaCoinQuestDojo.currentId = 0
    -- 重置boss血量
    self.gachaCoinQuestDojo.bossHpPercent = 1
    -- 卡牌状态
    self.gachaCoinQuestDojo.cardsInfo = {}

    -- 广播数据变动
    Events.Broadcast(Constants.EventNames.GachaCoinQuestGiveUpQuest)
end

---DrawChallengeTaskRewards 领取挑战关卡任务的奖励
---@param questId integer @ 关卡id
---@param taskId integer @ 任务id
---@param taskState GachaCoinQuestConstants.Defines.TaskState 任务状态
function GachaCoinQuestComponent:DrawChallengeTaskRewards(questId, taskId, taskState)
    if nil == self.gachaCoinQuestDojo.copyChallengeInfo[tostring(questId)] then
        self.gachaCoinQuestDojo.copyChallengeInfo[tostring(questId)] = {}
    end
    self.gachaCoinQuestDojo.copyChallengeInfo[tostring(questId)][tostring(taskId)] = taskState

    -- 广播数据变动
    Events.Broadcast(
        Constants.EventNames.GachaCoinQuestTaskDrawRewards,
        {questId = questId, taskId = taskId, taskState = taskState}
    )
end


