function GachaCoinQuestComponent:SetCurChallengeLevel(levelId)
    self.curChallengeLevelId = levelId
end

function GachaCoinQuestComponent:GetCurChallengeLevel()
    return self.curChallengeLevelId
end

--卡牌是否再黑名单
function GachaCoinQuestComponent:IsCardInBlackList(cardDojo)
    if not cardDojo then
        return false
    end
    if not self.gachaCoinQuestDojo then
        return false
    end
    if not self.gachaCoinQuestDojo.cardsInfo then
        return false
    end

    for k, v in pairs(self.gachaCoinQuestDojo.cardsInfo) do
        if checkNumber(cardDojo.id) == checkNumber(v) then
            return true
        end
    end
    return false
end

return GachaCoinQuestComponent